(72, N'Sandwich trứng phô mai', N'mon-chay-72', N'Sandwich trứng phô mai: công thức tham khảo với Bánh mì nguyên cám, Đậu hũ trắng, Hạt điều, Nấm đùi gà.', N'https://images.pexels.com/photos/1040685/pexels-photo-1040685.jpeg?auto=compress&cs=tinysrgb&w=1200', 47, 1.00, N'phần', 750, 43.70, 94.80, 25.60, N'LACTO_OVO', 1, '2026-10-13T23:56:11.791', '2026-10-13T23:56:11.791'),
(73, N'Cơm tấm chay sườn nấm tham khảo', N'com-tam-chay-suon-nam-tham-khao', N'Mình muốn làm mới bữa cơm quen thuộc bằng phiên bản chay. Cơm tấm chay sườn nấm vẫn giữ vị đậm đà nhưng nhẹ nhàng hơn cho bữa tối.', N'https://images.pexels.com/photos/723198/pexels-photo-723198.jpeg', 36, NULL, NULL, 430, 16.50, 52.00, 14.00, N'VEGAN', 1, '2026-10-14T02:59:43.923', '2026-10-14T02:59:43.923'),
(74, N'Phở cuốn chay chấm tương tham khảo', N'pho-cuon-chay-cham-tuong-tham-khao', N'Có những buổi chiều mình thích tự cuốn từng chiếc phở cuốn thật chậm. Phở cuốn chay chấm tương vừa nhẹ bụng vừa đủ đầy cho một bữa tối thanh đạm.', N'https://images.pexels.com/photos/1907244/pexels-photo-1907244.jpeg', 40, NULL, NULL, 290, 12.00, 34.00, 9.50, N'VEGAN', 1, '2026-10-14T03:00:56.680', '2026-10-14T03:00:56.680');
INSERT INTO recipes (recipe_id, dish_id, title, slug, description, instructions, prep_time_min, cook_time_min, servings, created_by, status, created_at, updated_at) VALUES
(1, 1, N'Công thức Phở nấm thuần chay', N'cong-thuc-mon-chay-01', N'Phở nấm thuần chay: công thức tham khảo với Nấm đùi gà, Bún gạo, Nấm hương, Cà rốt.', N'1. Sơ chế nấm đùi gà, bún gạo, nấm hương; rửa rau củ và cắt vừa ăn. 2. Nấu nước dùng rau củ với cà rốt và nấm khoảng 15–20 phút để tạo vị ngọt tự nhiên. 3. Nấu chín phần bún, mì hoặc ngũ cốc riêng; cho đạm thực vật và rau vào nước dùng đến khi chín. 4. Nêm nước tương và gia vị vừa ăn, chan nước dùng rồi thưởng thức nóng.', 15, 20, 2, 8, N'verified', '2026-10-13T23:56:11.865', '2026-10-13T23:56:11.865'),
(2, 2, N'Công thức Bún Huế chay', N'cong-thuc-mon-chay-02', N'Bún Huế chay: công thức tham khảo với Bún gạo, Nấm hương, Cà rốt, Đậu hũ trắng.', N'1. Sơ chế bún gạo, nấm hương, cà rốt; rửa rau củ và cắt vừa ăn. 2. Nấu nước dùng rau củ với cà rốt và nấm khoảng 15–20 phút để tạo vị ngọt tự nhiên. 3. Nấu chín phần bún, mì hoặc ngũ cốc riêng; cho đạm thực vật và rau vào nước dùng đến khi chín. 4. Nêm nước tương và gia vị vừa ăn, chan nước dùng rồi thưởng thức nóng.', 20, 25, 2, 9, N'verified', '2026-10-13T23:56:11.865', '2026-10-13T23:56:11.865'),
(3, 3, N'Công thức Bún riêu đậu hũ chay', N'cong-thuc-mon-chay-03', N'Bún riêu đậu hũ chay: công thức tham khảo với Đậu hũ trắng, Bún gạo, Nấm hương, Cà rốt.', N'1. Sơ chế đậu hũ trắng, bún gạo, nấm hương; rửa rau củ và cắt vừa ăn. 2. Nấu nước dùng rau củ với cà rốt và nấm khoảng 15–20 phút để tạo vị ngọt tự nhiên. 3. Nấu chín phần bún, mì hoặc ngũ cốc riêng; cho đạm thực vật và rau vào nước dùng đến khi chín. 4. Nêm nước tương và gia vị vừa ăn, chan nước dùng rồi thưởng thức nóng.', 25, 30, 2, 10, N'verified', '2026-10-13T23:56:11.865', '2026-10-13T23:56:11.865'),
(4, 4, N'Công thức Hủ tiếu rau củ', N'cong-thuc-mon-chay-04', N'Hủ tiếu rau củ: công thức tham khảo với Bún gạo, Nấm hương, Cà rốt, Đậu hũ trắng.', N'1. Sơ chế bún gạo, nấm hương, cà rốt; rửa rau củ và cắt vừa ăn. 2. Nấu nước dùng rau củ với cà rốt và nấm khoảng 15–20 phút để tạo vị ngọt tự nhiên. 3. Nấu chín phần bún, mì hoặc ngũ cốc riêng; cho đạm thực vật và rau vào nước dùng đến khi chín. 4. Nêm nước tương và gia vị vừa ăn, chan nước dùng rồi thưởng thức nóng.', 10, 35, 2, 11, N'verified', '2026-10-13T23:56:11.865', '2026-10-13T23:56:11.865'),
(5, 5, N'Công thức Mì Quảng chay', N'cong-thuc-mon-chay-05', N'Mì Quảng chay: công thức tham khảo với Bún gạo, Nấm hương, Cà rốt, Đậu hũ trắng.', N'1. Sơ chế bún gạo, nấm hương, cà rốt; rửa sạch, để ráo và cắt miếng vừa ăn. 2. Nấu chín phần tinh bột hoặc ngũ cốc chính nếu có. 3. Áp chảo hoặc xào nấm, đạm thực vật và rau củ theo thứ tự lâu chín trước, nhanh chín sau. 4. Nêm gia vị thực vật vừa ăn, kết hợp các thành phần và bày ra đĩa.', 15, 15, 2, 12, N'verified', '2026-10-13T23:56:11.865', '2026-10-13T23:56:11.865'),
