INSERT INTO contents (content_id, user_id, content_type, category_id, title, slug, body, media_url, thumbnail_url, duration_sec, status, view_count, created_at, updated_at) VALUES
(1, 7, N'BLOG', 33, N'Chia sẻ cách làm Phở nấm thuần chay', N'noi-dung-thuan-chay-001', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là phở nấm thuần chay. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":20,"servings":2,"nutrition":{"calories":297,"proteinG":12.7,"carbsG":34.1,"fatG":7.8,"fiberG":5.4,"sodiumMg":253},"ingredients":[{"name":"Nấm đùi gà","quantity":"150","unit":"g","isCustom":false},{"name":"Bún gạo","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm phở nấm thuần chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt nấm đùi gà, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm phở nấm thuần chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm phở nấm thuần chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt nấm đùi gà, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm phở nấm thuần chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://bizweb.dktcdn.net/100/524/612/files/2-24d66f54-ab37-433b-9b4d-cca7d2444a19.jpg?v=1750064853509', NULL, N'published', 198, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(2, 8, N'BLOG', 40, N'Góc bếp: Bún Huế chay', N'noi-dung-thuan-chay-002', N'{"version":1,"story":"bún Huế chay làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":25,"servings":2,"nutrition":{"calories":314,"proteinG":14.4,"carbsG":36.2,"fatG":8.6,"fiberG":5.8,"sodiumMg":266},"ingredients":[{"name":"Bún gạo","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của video hướng dẫn bún huế chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn bún huế chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của video hướng dẫn bún huế chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn bún huế chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://file.hstatic.net/200000438723/file/1_21d4c8d55d0645bc8935c93c4b36969c_grande.png', NULL, N'published', 416, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(3, 9, N'BLOG', 47, N'Chia sẻ cách làm Bún riêu đậu hũ chay', N'noi-dung-thuan-chay-003', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như bún riêu đậu hũ chay. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":30,"servings":2,"nutrition":{"calories":331,"proteinG":16.1,"carbsG":38.3,"fatG":9.4,"fiberG":6.2,"sodiumMg":279},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Bún gạo","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún riêu đậu hũ chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún riêu đậu hũ chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún riêu đậu hũ chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún riêu đậu hũ chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://file.hstatic.net/200000438723/file/1_ebf9a78fe7e84ef09f80689c4a1a4417_grande.png', NULL, N'published', 52, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(4, 10, N'BLOG', 29, N'Góc bếp: Hủ tiếu rau củ', N'noi-dung-thuan-chay-004', N'{"version":1,"story":"Mình tình cờ biết đến hủ tiếu rau củ trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":35,"servings":2,"nutrition":{"calories":348,"proteinG":17.8,"carbsG":40.4,"fatG":10.2,"fiberG":6.6,"sodiumMg":292},"ingredients":[{"name":"Bún gạo","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của video hướng dẫn hủ tiếu rau củ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn hủ tiếu rau củ theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của video hướng dẫn hủ tiếu rau củ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn hủ tiếu rau củ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/14552781/pexels-photo-14552781.jpeg', NULL, N'published', 12, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(5, 11, N'BLOG', 36, N'Chia sẻ cách làm Mì Quảng chay', N'noi-dung-thuan-chay-005', N'{"version":1,"story":"Điều mình thích ở mì Quảng chay là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":15,"servings":2,"nutrition":{"calories":365,"proteinG":19.5,"carbsG":42.5,"fatG":11.0,"fiberG":7.0,"sodiumMg":305},"ingredients":[{"name":"Bún gạo","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm mì quảng chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm mì quảng chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm mì quảng chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm mì quảng chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/38631737/pexels-photo-38631737.jpeg', NULL, N'published', 36, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(6, 12, N'BLOG', 43, N'Góc bếp: Cơm gạo lứt đậu hũ sốt mè', N'noi-dung-thuan-chay-006', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức cơm gạo lứt đậu hũ sốt mè. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":20,"servings":2,"nutrition":{"calories":382,"proteinG":21.2,"carbsG":44.6,"fatG":11.8,"fiberG":7.4,"sodiumMg":318},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Gạo lứt","quantity":"100","unit":"g","isCustom":false},{"name":"Mè trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"15","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu hũ trắng, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho mè trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm gạo lứt đậu hũ sốt mè theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu hũ trắng, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho mè trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm gạo lứt đậu hũ sốt mè theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/36982099/pexels-photo-36982099.jpeg', NULL, N'published', 458, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(7, 13, N'BLOG', 50, N'Chia sẻ cách làm Cơm gạo lứt tempeh nướng', N'noi-dung-thuan-chay-007', N'{"version":1,"story":"cơm gạo lứt tempeh nướng mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":25,"servings":2,"nutrition":{"calories":399,"proteinG":22.9,"carbsG":46.7,"fatG":12.6,"fiberG":7.8,"sodiumMg":331},"ingredients":[{"name":"Tempeh","quantity":"150","unit":"g","isCustom":false},{"name":"Gạo lứt","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái tempeh, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm gạo lứt tempeh nướng theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái tempeh, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm gạo lứt tempeh nướng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/38499048/pexels-photo-38499048.jpeg', NULL, N'published', 115, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(8, 14, N'BLOG', 32, N'Góc bếp: Cơm chiên rau củ thuần chay', N'noi-dung-thuan-chay-008', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu cơm chiên rau củ thuần chay. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":30,"servings":2,"nutrition":{"calories":416,"proteinG":24.6,"carbsG":48.8,"fatG":13.4,"fiberG":8.2,"sodiumMg":344},"ingredients":[{"name":"Gạo trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái gạo trắng, cà rốt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cải thìa vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm chiên rau củ thuần chay theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái gạo trắng, cà rốt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cải thìa vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm chiên rau củ thuần chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/28867521/pexels-photo-28867521.jpeg', NULL, N'published', 345, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(9, 15, N'BLOG', 39, N'Chia sẻ cách làm Cơm bí đỏ đậu gà', N'noi-dung-thuan-chay-009', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là cơm bí đỏ đậu gà. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":35,"servings":2,"nutrition":{"calories":433,"proteinG":11.3,"carbsG":50.9,"fatG":14.2,"fiberG":8.6,"sodiumMg":357},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Bí đỏ","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu gà, bí đỏ thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm bí đỏ đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu gà, bí đỏ thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm bí đỏ đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/6546437/pexels-photo-6546437.jpeg', NULL, N'published', 932, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(10, 16, N'BLOG', 46, N'Góc bếp: Cơm nấm hương cải thìa', N'noi-dung-thuan-chay-010', N'{"version":1,"story":"cơm nấm hương cải thìa làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":15,"servings":2,"nutrition":{"calories":450,"proteinG":13.0,"carbsG":53.0,"fatG":15.0,"fiberG":9.0,"sodiumMg":370},"ingredients":[{"name":"Cải thìa","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"15","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái cải thìa, nấm hương thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho nấm đùi gà vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm nấm hương cải thìa theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái cải thìa, nấm hương thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho nấm đùi gà vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm nấm hương cải thìa theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/12266296/pexels-photo-12266296.jpeg', NULL, N'published', 33, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(11, 17, N'BLOG', 28, N'Chia sẻ cách làm Cháo yến mạch nấm', N'noi-dung-thuan-chay-011', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như cháo yến mạch nấm. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":20,"servings":2,"nutrition":{"calories":467,"proteinG":14.7,"carbsG":55.1,"fatG":15.8,"fiberG":9.4,"sodiumMg":383},"ingredients":[{"name":"Yến mạch","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế yến mạch, nấm đùi gà; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm cháo yến mạch nấm theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế yến mạch, nấm đùi gà; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm cháo yến mạch nấm theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/4071738/pexels-photo-4071738.jpeg', NULL, N'under_review', 43, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(12, 18, N'BLOG', 35, N'Góc bếp: Cháo đậu xanh bí đỏ', N'noi-dung-thuan-chay-012', N'{"version":1,"story":"Mình tình cờ biết đến cháo đậu xanh bí đỏ trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":25,"servings":2,"nutrition":{"calories":484,"proteinG":16.4,"carbsG":57.2,"fatG":16.6,"fiberG":9.8,"sodiumMg":396},"ingredients":[{"name":"Bí đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Yến mạch","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế bí đỏ, yến mạch; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn cháo đậu xanh bí đỏ theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế bí đỏ, yến mạch; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn cháo đậu xanh bí đỏ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/5652188/pexels-photo-5652188.jpeg', NULL, N'published', 925, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(13, 19, N'BLOG', 42, N'Chia sẻ cách làm Bún xào rau củ đậu hũ', N'noi-dung-thuan-chay-013', N'{"version":1,"story":"Điều mình thích ở bún xào rau củ đậu hũ là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":30,"servings":2,"nutrition":{"calories":501,"proteinG":18.1,"carbsG":59.3,"fatG":17.4,"fiberG":10.2,"sodiumMg":409},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Bún gạo","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún xào rau củ đậu hũ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún xào rau củ đậu hũ theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún xào rau củ đậu hũ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún xào rau củ đậu hũ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1435893/pexels-photo-1435893.jpeg', NULL, N'published', 104, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(14, 20, N'BLOG', 49, N'Góc bếp: Mì soba sốt mè', N'noi-dung-thuan-chay-014', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức mì soba sốt mè. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":35,"servings":2,"nutrition":{"calories":288,"proteinG":19.8,"carbsG":33.4,"fatG":7.2,"fiberG":10.6,"sodiumMg":422},"ingredients":[{"name":"Mè trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế mè trắng và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn mì soba sốt mè theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế mè trắng và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn mì soba sốt mè theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/9141774/pexels-photo-9141774.jpeg', NULL, N'published', 98, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(15, 21, N'BLOG', 31, N'Chia sẻ cách làm Mì soba nấm cải bó xôi', N'noi-dung-thuan-chay-015', N'{"version":1,"story":"mì soba nấm cải bó xôi mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":15,"servings":2,"nutrition":{"calories":305,"proteinG":21.5,"carbsG":35.5,"fatG":8.0,"fiberG":5.0,"sodiumMg":435},"ingredients":[{"name":"Cải bó xôi","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế cải bó xôi và nấm đùi gà; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm mì soba nấm cải bó xôi theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế cải bó xôi và nấm đùi gà; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm mì soba nấm cải bó xôi theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/5182118/pexels-photo-5182118.jpeg', NULL, N'published', 916, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(16, 22, N'BLOG', 38, N'Góc bếp: Pasta sốt cà chua đậu lăng', N'noi-dung-thuan-chay-016', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu pasta sốt cà chua đậu lăng. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":20,"servings":2,"nutrition":{"calories":322,"proteinG":23.2,"carbsG":37.6,"fatG":8.8,"fiberG":5.4,"sodiumMg":448},"ingredients":[{"name":"Đậu lăng đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế đậu lăng đỏ và cà chua; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn pasta sốt cà chua đậu lăng theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế đậu lăng đỏ và cà chua; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn pasta sốt cà chua đậu lăng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/9304090/pexels-photo-9304090.jpeg', NULL, N'published', 55, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(17, 23, N'BLOG', 45, N'Chia sẻ cách làm Pasta sốt kem hạt điều', N'noi-dung-thuan-chay-017', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là pasta sốt kem hạt điều. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":25,"servings":2,"nutrition":{"calories":339,"proteinG":24.9,"carbsG":39.7,"fatG":9.6,"fiberG":5.8,"sodiumMg":461},"ingredients":[{"name":"Hạt điều","quantity":"150","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế hạt điều và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm pasta sốt kem hạt điều theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế hạt điều và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm pasta sốt kem hạt điều theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/36946663/pexels-photo-36946663.jpeg', NULL, N'flagged', 942, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(18, 24, N'BLOG', 27, N'Góc bếp: Salad quinoa đậu gà', N'noi-dung-thuan-chay-018', N'{"version":1,"story":"salad quinoa đậu gà làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":30,"servings":2,"nutrition":{"calories":356,"proteinG":11.6,"carbsG":41.8,"fatG":10.4,"fiberG":6.2,"sodiumMg":244},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Quinoa","quantity":"100","unit":"g","isCustom":false},{"name":"Dưa leo","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false},{"name":"Bắp cải tím","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế đậu gà và quinoa, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu gà, quinoa và dưa leo với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn salad quinoa đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế đậu gà và quinoa, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu gà, quinoa và dưa leo với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn salad quinoa đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/33158371/pexels-photo-33158371.jpeg', NULL, N'published', 546, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(19, 25, N'BLOG', 34, N'Chia sẻ cách làm Salad kale bơ hạt', N'noi-dung-thuan-chay-019', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như salad kale bơ hạt. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":35,"servings":2,"nutrition":{"calories":373,"proteinG":13.3,"carbsG":43.9,"fatG":11.2,"fiberG":6.6,"sodiumMg":257},"ingredients":[{"name":"Cải kale","quantity":"150","unit":"g","isCustom":false},{"name":"Dưa leo","quantity":"100","unit":"g","isCustom":false},{"name":"Bơ","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false},{"name":"Bắp cải tím","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu gà","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế cải kale và dưa leo, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều cải kale, dưa leo và bơ với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần chia sẻ cách làm salad kale bơ hạt theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế cải kale và dưa leo, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều cải kale, dưa leo và bơ với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần chia sẻ cách làm salad kale bơ hạt theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/34337147/pexels-photo-34337147.jpeg', NULL, N'published', 409, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
