(21, 27, N'BLOG', 48, N'Chia sẻ cách làm Salad khoai lang nướng', N'noi-dung-thuan-chay-021', N'{"version":1,"story":"Điều mình thích ở salad khoai lang nướng là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":20,"servings":2,"nutrition":{"calories":407,"proteinG":16.7,"carbsG":48.1,"fatG":12.8,"fiberG":7.4,"sodiumMg":283},"ingredients":[{"name":"Khoai lang","quantity":"150","unit":"g","isCustom":false},{"name":"Dưa leo","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Bắp cải tím","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu gà","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế khoai lang và dưa leo, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều khoai lang, dưa leo và cà chua với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần chia sẻ cách làm salad khoai lang nướng theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế khoai lang và dưa leo, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều khoai lang, dưa leo và cà chua với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần chia sẻ cách làm salad khoai lang nướng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/4519044/pexels-photo-4519044.jpeg', NULL, N'published', 6937, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(22, 28, N'BLOG', 30, N'Góc bếp: Gỏi cuốn đậu hũ', N'noi-dung-thuan-chay-022', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức gỏi cuốn đậu hũ. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":25,"servings":2,"nutrition":{"calories":424,"proteinG":18.4,"carbsG":50.2,"fatG":13.6,"fiberG":7.8,"sodiumMg":296},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế đậu hũ trắng và nấm đùi gà, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu hũ trắng, nấm đùi gà và cà rốt với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn gỏi cuốn đậu hũ theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế đậu hũ trắng và nấm đùi gà, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu hũ trắng, nấm đùi gà và cà rốt với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn gỏi cuốn đậu hũ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/6832043/pexels-photo-6832043.jpeg', NULL, N'under_review', 34, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(23, 29, N'BLOG', 37, N'Chia sẻ cách làm Cuốn rau củ sốt đậu phộng', N'noi-dung-thuan-chay-023', N'{"version":1,"story":"cuốn rau củ sốt đậu phộng mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":30,"servings":2,"nutrition":{"calories":441,"proteinG":20.1,"carbsG":52.3,"fatG":14.4,"fiberG":8.2,"sodiumMg":309},"ingredients":[{"name":"Nấm đùi gà","quantity":"150","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế nấm đùi gà, cà rốt; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý nấm đùi gà trước đến khi vừa chín.","Thêm cà rốt và đậu hũ trắng, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cuốn rau củ sốt đậu phộng theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế nấm đùi gà, cà rốt; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý nấm đùi gà trước đến khi vừa chín.","Thêm cà rốt và đậu hũ trắng, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cuốn rau củ sốt đậu phộng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/36165416/pexels-photo-36165416.jpeg', NULL, N'published', 4215, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(24, 30, N'BLOG', 44, N'Góc bếp: Đậu hũ kho nấm', N'noi-dung-thuan-chay-024', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu đậu hũ kho nấm. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":35,"servings":2,"nutrition":{"calories":458,"proteinG":21.8,"carbsG":54.4,"fatG":15.2,"fiberG":8.6,"sodiumMg":322},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế đậu hũ trắng, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu hũ trắng trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn đậu hũ kho nấm theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế đậu hũ trắng, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu hũ trắng trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn đậu hũ kho nấm theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/37297769/pexels-photo-37297769.jpeg', NULL, N'published', 78, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(25, 31, N'BLOG', 26, N'Chia sẻ cách làm Đậu hũ sốt cà chua', N'noi-dung-thuan-chay-025', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là đậu hũ sốt cà chua. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":15,"servings":2,"nutrition":{"calories":475,"proteinG":23.5,"carbsG":56.5,"fatG":16.0,"fiberG":9.0,"sodiumMg":335},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế đậu hũ trắng, cà chua; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu hũ trắng trước đến khi vừa chín.","Thêm cà chua và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm đậu hũ sốt cà chua theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế đậu hũ trắng, cà chua; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu hũ trắng trước đến khi vừa chín.","Thêm cà chua và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm đậu hũ sốt cà chua theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/35672957/pexels-photo-35672957.jpeg', NULL, N'published', 9, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(26, 32, N'BLOG', 33, N'Góc bếp: Đậu hũ áp chảo sốt miso', N'noi-dung-thuan-chay-026', N'{"version":1,"story":"đậu hũ áp chảo sốt miso làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":20,"servings":2,"nutrition":{"calories":492,"proteinG":25.2,"carbsG":58.6,"fatG":16.8,"fiberG":9.4,"sodiumMg":348},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Tương miso","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế đậu hũ trắng, tương miso; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu hũ trắng trước đến khi vừa chín.","Thêm tương miso và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn đậu hũ áp chảo sốt miso theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế đậu hũ trắng, tương miso; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu hũ trắng trước đến khi vừa chín.","Thêm tương miso và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn đậu hũ áp chảo sốt miso theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/6120232/pexels-photo-6120232.jpeg', NULL, N'published', 90, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(27, 33, N'BLOG', 40, N'Chia sẻ cách làm Tempeh kho tiêu', N'noi-dung-thuan-chay-027', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như tempeh kho tiêu. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":25,"servings":2,"nutrition":{"calories":509,"proteinG":11.9,"carbsG":32.7,"fatG":17.6,"fiberG":9.8,"sodiumMg":361},"ingredients":[{"name":"Tempeh","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế tempeh, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý tempeh trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm tempeh kho tiêu theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế tempeh, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý tempeh trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm tempeh kho tiêu theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/36344175/pexels-photo-36344175.jpeg', NULL, N'published', 1430, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(28, 34, N'BLOG', 47, N'Góc bếp: Tempeh nướng sốt mè', N'noi-dung-thuan-chay-028', N'{"version":1,"story":"Mình tình cờ biết đến tempeh nướng sốt mè trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":30,"servings":2,"nutrition":{"calories":296,"proteinG":13.6,"carbsG":34.8,"fatG":7.4,"fiberG":10.2,"sodiumMg":374},"ingredients":[{"name":"Tempeh","quantity":"150","unit":"g","isCustom":false},{"name":"Mè trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế tempeh, mè trắng; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý tempeh trước đến khi vừa chín.","Thêm mè trắng và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn tempeh nướng sốt mè theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế tempeh, mè trắng; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý tempeh trước đến khi vừa chín.","Thêm mè trắng và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn tempeh nướng sốt mè theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/3026805/pexels-photo-3026805.jpeg', NULL, N'published', 73, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(29, 35, N'BLOG', 29, N'Chia sẻ cách làm Cà ri đậu gà', N'noi-dung-thuan-chay-029', N'{"version":1,"story":"Điều mình thích ở cà ri đậu gà là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":35,"servings":2,"nutrition":{"calories":313,"proteinG":15.3,"carbsG":36.9,"fatG":8.2,"fiberG":10.6,"sodiumMg":387},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế đậu gà, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu gà trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cà ri đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế đậu gà, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu gà trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cà ri đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/9213999/pexels-photo-9213999.jpeg', NULL, N'published', 99, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(30, 36, N'BLOG', 36, N'Góc bếp: Cà ri đậu lăng đỏ', N'noi-dung-thuan-chay-030', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức cà ri đậu lăng đỏ. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":15,"servings":2,"nutrition":{"calories":330,"proteinG":17.0,"carbsG":39.0,"fatG":9.0,"fiberG":5.0,"sodiumMg":400},"ingredients":[{"name":"Đậu lăng đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế đậu lăng đỏ, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu lăng đỏ trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn cà ri đậu lăng đỏ theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế đậu lăng đỏ, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu lăng đỏ trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn cà ri đậu lăng đỏ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/7189421/pexels-photo-7189421.jpeg', NULL, N'published', 11, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(31, 37, N'BLOG', 43, N'Chia sẻ cách làm Cà ri bí đỏ nước cốt dừa', N'noi-dung-thuan-chay-031', N'{"version":1,"story":"cà ri bí đỏ nước cốt dừa mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":20,"servings":2,"nutrition":{"calories":347,"proteinG":18.7,"carbsG":41.1,"fatG":9.8,"fiberG":5.4,"sodiumMg":413},"ingredients":[{"name":"Bí đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Nước cốt dừa","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế bí đỏ, nước cốt dừa; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý bí đỏ trước đến khi vừa chín.","Thêm nước cốt dừa và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cà ri bí đỏ nước cốt dừa theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế bí đỏ, nước cốt dừa; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý bí đỏ trước đến khi vừa chín.","Thêm nước cốt dừa và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cà ri bí đỏ nước cốt dừa theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/17902962/pexels-photo-17902962.jpeg', NULL, N'published', 10, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(32, 38, N'BLOG', 50, N'Góc bếp: Súp bí đỏ hạt điều', N'noi-dung-thuan-chay-032', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu súp bí đỏ hạt điều. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":25,"servings":2,"nutrition":{"calories":364,"proteinG":20.4,"carbsG":43.2,"fatG":10.6,"fiberG":5.8,"sodiumMg":426},"ingredients":[{"name":"Bí đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Hạt điều","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế bí đỏ, hạt điều; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn súp bí đỏ hạt điều theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế bí đỏ, hạt điều; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn súp bí đỏ hạt điều theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/5987437/pexels-photo-5987437.jpeg', NULL, N'published', 155, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(33, 39, N'BLOG', 32, N'Chia sẻ cách làm Súp đậu lăng cà chua', N'noi-dung-thuan-chay-033', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là súp đậu lăng cà chua. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":30,"servings":2,"nutrition":{"calories":381,"proteinG":22.1,"carbsG":45.3,"fatG":11.4,"fiberG":6.2,"sodiumMg":439},"ingredients":[{"name":"Đậu lăng đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế đậu lăng đỏ, cà chua; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm súp đậu lăng cà chua theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế đậu lăng đỏ, cà chua; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm súp đậu lăng cà chua theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/3832360/pexels-photo-3832360.jpeg', NULL, N'under_review', 118, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(34, 40, N'BLOG', 39, N'Góc bếp: Súp miso rong biển đậu hũ', N'noi-dung-thuan-chay-034', N'{"version":1,"story":"súp miso rong biển đậu hũ làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":35,"servings":2,"nutrition":{"calories":398,"proteinG":23.8,"carbsG":47.4,"fatG":12.2,"fiberG":6.6,"sodiumMg":452},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Tương miso","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế đậu hũ trắng, tương miso; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn súp miso rong biển đậu hũ theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế đậu hũ trắng, tương miso; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn súp miso rong biển đậu hũ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/31256392/pexels-photo-31256392.jpeg', NULL, N'flagged', 2946, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(35, 41, N'BLOG', 46, N'Chia sẻ cách làm Súp bông cải xanh', N'noi-dung-thuan-chay-035', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như súp bông cải xanh. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":15,"servings":2,"nutrition":{"calories":415,"proteinG":25.5,"carbsG":49.5,"fatG":13.0,"fiberG":7.0,"sodiumMg":465},"ingredients":[{"name":"Bông cải xanh","quantity":"150","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế bông cải xanh, cà rốt; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm nấm đùi gà, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm súp bông cải xanh theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế bông cải xanh, cà rốt; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm nấm đùi gà, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm súp bông cải xanh theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/14774456/pexels-photo-14774456.jpeg', NULL, N'published', 901, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(36, 42, N'BLOG', 28, N'Góc bếp: Buddha bowl quinoa', N'noi-dung-thuan-chay-036', N'{"version":1,"story":"Mình tình cờ biết đến buddha bowl quinoa trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":20,"servings":2,"nutrition":{"calories":432,"proteinG":12.2,"carbsG":51.6,"fatG":13.8,"fiberG":7.4,"sodiumMg":248},"ingredients":[{"name":"Quinoa","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái quinoa, nấm đùi gà thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cà rốt vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn buddha bowl quinoa theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái quinoa, nấm đùi gà thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cà rốt vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn buddha bowl quinoa theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/4375373/pexels-photo-4375373.jpeg', NULL, N'published', 109, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(37, 43, N'BLOG', 35, N'Chia sẻ cách làm Buddha bowl gạo lứt', N'noi-dung-thuan-chay-037', N'{"version":1,"story":"Điều mình thích ở buddha bowl gạo lứt là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":25,"servings":2,"nutrition":{"calories":449,"proteinG":13.9,"carbsG":53.7,"fatG":14.6,"fiberG":7.8,"sodiumMg":261},"ingredients":[{"name":"Gạo lứt","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế gạo lứt, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý gạo lứt trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm buddha bowl gạo lứt theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế gạo lứt, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý gạo lứt trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm buddha bowl gạo lứt theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/9218779/pexels-photo-9218779.jpeg', NULL, N'published', 822, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(38, 44, N'BLOG', 42, N'Góc bếp: Bowl khoai lang đậu đen', N'noi-dung-thuan-chay-038', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức bowl khoai lang đậu đen. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":30,"servings":2,"nutrition":{"calories":466,"proteinG":15.6,"carbsG":55.8,"fatG":15.4,"fiberG":8.2,"sodiumMg":274},"ingredients":[{"name":"Đậu đen","quantity":"150","unit":"g","isCustom":false},{"name":"Khoai lang","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế đậu đen, khoai lang; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu đen trước đến khi vừa chín.","Thêm khoai lang và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn bowl khoai lang đậu đen theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế đậu đen, khoai lang; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu đen trước đến khi vừa chín.","Thêm khoai lang và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn bowl khoai lang đậu đen theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/36071503/pexels-photo-36071503.jpeg', NULL, N'published', 15, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(39, 45, N'BLOG', 49, N'Chia sẻ cách làm Bánh mì đậu hũ nướng', N'noi-dung-thuan-chay-039', N'{"version":1,"story":"bánh mì đậu hũ nướng mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":35,"servings":2,"nutrition":{"calories":483,"proteinG":17.3,"carbsG":57.9,"fatG":16.2,"fiberG":8.6,"sodiumMg":287},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Bánh mì nguyên cám","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị đậu hũ trắng và bánh mì nguyên cám, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp cà chua với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần chia sẻ cách làm bánh mì đậu hũ nướng theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị đậu hũ trắng và bánh mì nguyên cám, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp cà chua với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần chia sẻ cách làm bánh mì đậu hũ nướng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/35020121/pexels-photo-35020121.jpeg', NULL, N'published', 416, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(40, 46, N'BLOG', 31, N'Góc bếp: Bánh mì tempeh rau củ', N'noi-dung-thuan-chay-040', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu bánh mì tempeh rau củ. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":15,"servings":2,"nutrition":{"calories":500,"proteinG":19.0,"carbsG":32.0,"fatG":17.0,"fiberG":9.0,"sodiumMg":300},"ingredients":[{"name":"Tempeh","quantity":"150","unit":"g","isCustom":false},{"name":"Bánh mì nguyên cám","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị tempeh và bánh mì nguyên cám, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp cà chua với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần video hướng dẫn bánh mì tempeh rau củ theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị tempeh và bánh mì nguyên cám, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp cà chua với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần video hướng dẫn bánh mì tempeh rau củ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/11390376/pexels-photo-11390376.jpeg', NULL, N'published', 63, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(41, 47, N'BLOG', 38, N'Chia sẻ cách làm Yến mạch chuối hạt chia', N'noi-dung-thuan-chay-041', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là yến mạch chuối hạt chia. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":20,"servings":2,"nutrition":{"calories":287,"proteinG":20.7,"carbsG":34.1,"fatG":17.8,"fiberG":9.4,"sodiumMg":313},"ingredients":[{"name":"Yến mạch","quantity":"150","unit":"g","isCustom":false},{"name":"Chuối","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế yến mạch, chuối; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý yến mạch trước đến khi vừa chín.","Thêm chuối và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm yến mạch chuối hạt chia theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế yến mạch, chuối; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý yến mạch trước đến khi vừa chín.","Thêm chuối và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm yến mạch chuối hạt chia theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/7167847/pexels-photo-7167847.jpeg', NULL, N'published', 108, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(42, 48, N'BLOG', 45, N'Góc bếp: Yến mạch táo quế', N'noi-dung-thuan-chay-042', N'{"version":1,"story":"yến mạch táo quế làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":25,"servings":2,"nutrition":{"calories":304,"proteinG":22.4,"carbsG":36.2,"fatG":7.6,"fiberG":9.8,"sodiumMg":326},"ingredients":[{"name":"Yến mạch","quantity":"150","unit":"g","isCustom":false},{"name":"Táo","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế yến mạch, táo; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý yến mạch trước đến khi vừa chín.","Thêm táo và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn yến mạch táo quế theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế yến mạch, táo; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý yến mạch trước đến khi vừa chín.","Thêm táo và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn yến mạch táo quế theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/8681420/pexels-photo-8681420.jpeg', NULL, N'published', 25, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(43, 49, N'BLOG', 27, N'Chia sẻ cách làm Overnight oats xoài dừa', N'noi-dung-thuan-chay-043', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như overnight oats xoài dừa. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":30,"servings":2,"nutrition":{"calories":321,"proteinG":24.1,"carbsG":38.3,"fatG":8.4,"fiberG":10.2,"sodiumMg":339},"ingredients":[{"name":"Xoài","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế xoài, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý xoài trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm overnight oats xoài dừa theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế xoài, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý xoài trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm overnight oats xoài dừa theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/6529941/pexels-photo-6529941.jpeg', NULL, N'published', 534, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(44, 50, N'BLOG', 34, N'Góc bếp: Pudding hạt chia dâu', N'noi-dung-thuan-chay-044', N'{"version":1,"story":"Mình tình cờ biết đến pudding hạt chia dâu trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":35,"servings":2,"nutrition":{"calories":338,"proteinG":25.8,"carbsG":40.4,"fatG":9.2,"fiberG":10.6,"sodiumMg":352},"ingredients":[{"name":"Dâu tây","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế dâu tây, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý dâu tây trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn pudding hạt chia dâu theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế dâu tây, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý dâu tây trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn pudding hạt chia dâu theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/17260332/pexels-photo-17260332.jpeg', NULL, N'under_review', 2576, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(45, 51, N'BLOG', 41, N'Chia sẻ cách làm Sinh tố chuối bơ đậu phộng', N'noi-dung-thuan-chay-045', N'{"version":1,"story":"Điều mình thích ở sinh tố chuối bơ đậu phộng là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":15,"servings":2,"nutrition":{"calories":355,"proteinG":12.5,"carbsG":42.5,"fatG":10.0,"fiberG":5.0,"sodiumMg":365},"ingredients":[{"name":"Bơ đậu phộng","quantity":"150","unit":"g","isCustom":false},{"name":"Chuối","quantity":"100","unit":"g","isCustom":false},{"name":"Bơ","quantity":"100","unit":"g","isCustom":false},{"name":"Sữa đậu nành","quantity":"15","unit":"g","isCustom":false},{"name":"Hạt chia","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch bơ đậu phộng và chuối, loại bỏ phần không ăn được rồi cắt nhỏ.","Cho bơ đậu phộng cùng chuối vào cối xay; thêm một ít nước hoặc sữa thực vật nếu cần.","Xay theo từng nhịp đến khi hỗn hợp mịn, nếm thử trước khi điều chỉnh độ ngọt.","Rót ra ly đã làm lạnh và thưởng thức ngay để giữ hương vị tươi — hoàn thiện phần chia sẻ cách làm sinh tố chuối bơ đậu phộng theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch bơ đậu phộng và chuối, loại bỏ phần không ăn được rồi cắt nhỏ.","Cho bơ đậu phộng cùng chuối vào cối xay; thêm một ít nước hoặc sữa thực vật nếu cần.","Xay theo từng nhịp đến khi hỗn hợp mịn, nếm thử trước khi điều chỉnh độ ngọt.","Rót ra ly đã làm lạnh và thưởng thức ngay để giữ hương vị tươi — hoàn thiện phần chia sẻ cách làm sinh tố chuối bơ đậu phộng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1098758/pexels-photo-1098758.jpeg', NULL, N'published', 13, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(46, 52, N'BLOG', 48, N'Góc bếp: Sinh tố xoài cải bó xôi', N'noi-dung-thuan-chay-046', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức sinh tố xoài cải bó xôi. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":20,"servings":2,"nutrition":{"calories":372,"proteinG":14.2,"carbsG":44.6,"fatG":10.8,"fiberG":5.4,"sodiumMg":378},"ingredients":[{"name":"Cải bó xôi","quantity":"150","unit":"g","isCustom":false},{"name":"Xoài","quantity":"100","unit":"g","isCustom":false},{"name":"Chuối","quantity":"100","unit":"g","isCustom":false},{"name":"Sữa đậu nành","quantity":"15","unit":"g","isCustom":false},{"name":"Hạt chia","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch cải bó xôi và xoài, loại bỏ phần không ăn được rồi cắt nhỏ.","Cho cải bó xôi cùng xoài vào cối xay; thêm một ít nước hoặc sữa thực vật nếu cần.","Xay theo từng nhịp đến khi hỗn hợp mịn, nếm thử trước khi điều chỉnh độ ngọt.","Rót ra ly đã làm lạnh và thưởng thức ngay để giữ hương vị tươi — hoàn thiện phần video hướng dẫn sinh tố xoài cải bó xôi theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch cải bó xôi và xoài, loại bỏ phần không ăn được rồi cắt nhỏ.","Cho cải bó xôi cùng xoài vào cối xay; thêm một ít nước hoặc sữa thực vật nếu cần.","Xay theo từng nhịp đến khi hỗn hợp mịn, nếm thử trước khi điều chỉnh độ ngọt.","Rót ra ly đã làm lạnh và thưởng thức ngay để giữ hương vị tươi — hoàn thiện phần video hướng dẫn sinh tố xoài cải bó xôi theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/6597063/pexels-photo-6597063.jpeg', NULL, N'published', 577, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(47, 53, N'BLOG', 30, N'Chia sẻ cách làm Sinh tố dâu sữa yến mạch', N'noi-dung-thuan-chay-047', N'{"version":1,"story":"sinh tố dâu sữa yến mạch mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":25,"servings":2,"nutrition":{"calories":389,"proteinG":15.9,"carbsG":46.7,"fatG":11.6,"fiberG":5.8,"sodiumMg":391},"ingredients":[{"name":"Yến mạch","quantity":"150","unit":"g","isCustom":false},{"name":"Sữa yến mạch","quantity":"100","unit":"g","isCustom":false},{"name":"Dâu tây","quantity":"100","unit":"g","isCustom":false},{"name":"Chuối","quantity":"15","unit":"g","isCustom":false},{"name":"Sữa đậu nành","quantity":"15","unit":"g","isCustom":false},{"name":"Hạt chia","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch yến mạch và sữa yến mạch, loại bỏ phần không ăn được rồi cắt nhỏ.","Cho yến mạch cùng sữa yến mạch vào cối xay; thêm một ít nước hoặc sữa thực vật nếu cần.","Xay theo từng nhịp đến khi hỗn hợp mịn, nếm thử trước khi điều chỉnh độ ngọt.","Rót ra ly đã làm lạnh và thưởng thức ngay để giữ hương vị tươi — hoàn thiện phần chia sẻ cách làm sinh tố dâu sữa yến mạch theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch yến mạch và sữa yến mạch, loại bỏ phần không ăn được rồi cắt nhỏ.","Cho yến mạch cùng sữa yến mạch vào cối xay; thêm một ít nước hoặc sữa thực vật nếu cần.","Xay theo từng nhịp đến khi hỗn hợp mịn, nếm thử trước khi điều chỉnh độ ngọt.","Rót ra ly đã làm lạnh và thưởng thức ngay để giữ hương vị tươi — hoàn thiện phần chia sẻ cách làm sinh tố dâu sữa yến mạch theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/20791352/pexels-photo-20791352.jpeg', NULL, N'published', 73, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(48, 54, N'BLOG', 37, N'Góc bếp: Khoai lang nướng đậu gà', N'noi-dung-thuan-chay-048', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu khoai lang nướng đậu gà. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":30,"servings":2,"nutrition":{"calories":406,"proteinG":17.6,"carbsG":48.8,"fatG":12.4,"fiberG":6.2,"sodiumMg":404},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Khoai lang","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế đậu gà, khoai lang; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu gà trước đến khi vừa chín.","Thêm khoai lang và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn khoai lang nướng đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế đậu gà, khoai lang; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý đậu gà trước đến khi vừa chín.","Thêm khoai lang và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn khoai lang nướng đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/5505470/pexels-photo-5505470.jpeg', NULL, N'published', 12, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(49, 55, N'BLOG', 44, N'Chia sẻ cách làm Bí đỏ nướng quinoa', N'noi-dung-thuan-chay-049', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là bí đỏ nướng quinoa. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":35,"servings":2,"nutrition":{"calories":423,"proteinG":19.3,"carbsG":50.9,"fatG":13.2,"fiberG":6.6,"sodiumMg":417},"ingredients":[{"name":"Quinoa","quantity":"150","unit":"g","isCustom":false},{"name":"Bí đỏ","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái quinoa, bí đỏ thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho nấm đùi gà vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm bí đỏ nướng quinoa theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái quinoa, bí đỏ thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho nấm đùi gà vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm bí đỏ nướng quinoa theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/4899793/pexels-photo-4899793.jpeg', NULL, N'published', 864, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(50, 56, N'BLOG', 26, N'Góc bếp: Bông cải xanh xào nấm', N'noi-dung-thuan-chay-050', N'{"version":1,"story":"bông cải xanh xào nấm làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":15,"servings":2,"nutrition":{"calories":440,"proteinG":21.0,"carbsG":53.0,"fatG":14.0,"fiberG":7.0,"sodiumMg":430},"ingredients":[{"name":"Bông cải xanh","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế bông cải xanh, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý bông cải xanh trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn bông cải xanh xào nấm theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế bông cải xanh, nấm đùi gà; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý bông cải xanh trước đến khi vừa chín.","Thêm nấm đùi gà và cà rốt, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn bông cải xanh xào nấm theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/35989075/pexels-photo-35989075.jpeg', NULL, N'published', 14, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(51, 57, N'BLOG', 33, N'Chia sẻ cách làm Cải thìa xào nấm hương', N'noi-dung-thuan-chay-051', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như cải thìa xào nấm hương. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":20,"servings":2,"nutrition":{"calories":457,"proteinG":22.7,"carbsG":55.1,"fatG":14.8,"fiberG":7.4,"sodiumMg":443},"ingredients":[{"name":"Cải thìa","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế cải thìa, nấm hương; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý cải thìa trước đến khi vừa chín.","Thêm nấm hương và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cải thìa xào nấm hương theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế cải thìa, nấm hương; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý cải thìa trước đến khi vừa chín.","Thêm nấm hương và nấm đùi gà, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm cải thìa xào nấm hương theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1410235/pexels-photo-1410235.jpeg', NULL, N'flagged', 240, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(52, 58, N'BLOG', 40, N'Góc bếp: Nấm đùi gà áp chảo', N'noi-dung-thuan-chay-052', N'{"version":1,"story":"Mình tình cờ biết đến nấm đùi gà áp chảo trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":25,"servings":2,"nutrition":{"calories":474,"proteinG":24.4,"carbsG":57.2,"fatG":15.6,"fiberG":7.8,"sodiumMg":456},"ingredients":[{"name":"Nấm đùi gà","quantity":"150","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế nấm đùi gà, cà rốt; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý nấm đùi gà trước đến khi vừa chín.","Thêm cà rốt và đậu hũ trắng, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn nấm đùi gà áp chảo theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế nấm đùi gà, cà rốt; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý nấm đùi gà trước đến khi vừa chín.","Thêm cà rốt và đậu hũ trắng, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần video hướng dẫn nấm đùi gà áp chảo theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/6823591/pexels-photo-6823591.jpeg', NULL, N'published', 85, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(53, 59, N'BLOG', 47, N'Chia sẻ cách làm Đậu gà rang giòn', N'noi-dung-thuan-chay-053', N'{"version":1,"story":"Điều mình thích ở đậu gà rang giòn là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":30,"servings":2,"nutrition":{"calories":491,"proteinG":11.1,"carbsG":59.3,"fatG":16.4,"fiberG":8.2,"sodiumMg":469},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu gà, nấm đùi gà thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cà rốt vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm đậu gà rang giòn theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu gà, nấm đùi gà thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cà rốt vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm đậu gà rang giòn theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/23384616/pexels-photo-23384616.jpeg', NULL, N'published', 3555, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(54, 60, N'BLOG', 29, N'Góc bếp: Edamame trộn mè', N'noi-dung-thuan-chay-054', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức edamame trộn mè. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":35,"servings":2,"nutrition":{"calories":508,"proteinG":12.8,"carbsG":33.4,"fatG":17.2,"fiberG":8.6,"sodiumMg":252},"ingredients":[{"name":"Edamame","quantity":"150","unit":"g","isCustom":false},{"name":"Mè trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế edamame và mè trắng, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều edamame, mè trắng và nấm đùi gà với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn edamame trộn mè theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế edamame và mè trắng, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều edamame, mè trắng và nấm đùi gà với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn edamame trộn mè theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/30358737/pexels-photo-30358737.jpeg', NULL, N'published', 9, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(55, 7, N'BLOG', 36, N'Chia sẻ cách làm Hummus đậu gà', N'noi-dung-thuan-chay-055', N'{"version":1,"story":"hummus đậu gà mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":15,"servings":2,"nutrition":{"calories":295,"proteinG":14.5,"carbsG":35.5,"fatG":7.0,"fiberG":9.0,"sodiumMg":265},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị đậu gà và nấm đùi gà, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp cà rốt với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần chia sẻ cách làm hummus đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị đậu gà và nấm đùi gà, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp cà rốt với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần chia sẻ cách làm hummus đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/19552439/pexels-photo-19552439.jpeg', NULL, N'under_review', 113, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(56, 8, N'BLOG', 43, N'Góc bếp: Bánh yến mạch chuối', N'noi-dung-thuan-chay-056', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu bánh yến mạch chuối. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":20,"servings":2,"nutrition":{"calories":312,"proteinG":16.2,"carbsG":37.6,"fatG":7.8,"fiberG":9.4,"sodiumMg":278},"ingredients":[{"name":"Yến mạch","quantity":"150","unit":"g","isCustom":false},{"name":"Chuối","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị yến mạch và chuối, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp nấm đùi gà với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần video hướng dẫn bánh yến mạch chuối theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị yến mạch và chuối, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp nấm đùi gà với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần video hướng dẫn bánh yến mạch chuối theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/37275988/pexels-photo-37275988.jpeg', NULL, N'published', 377, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(57, 9, N'BLOG', 50, N'Chia sẻ cách làm Trái cây hạt chia', N'noi-dung-thuan-chay-057', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là trái cây hạt chia. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":25,"servings":2,"nutrition":{"calories":329,"proteinG":17.9,"carbsG":39.7,"fatG":8.6,"fiberG":9.8,"sodiumMg":291},"ingredients":[{"name":"Nấm đùi gà","quantity":"150","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa sạch và sơ chế nấm đùi gà, cà rốt; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý nấm đùi gà trước đến khi vừa chín.","Thêm cà rốt và đậu hũ trắng, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm trái cây hạt chia theo khẩu vị trước khi phục vụ."],"steps":["Rửa sạch và sơ chế nấm đùi gà, cà rốt; chia nguyên liệu theo thời gian chín.","Làm nóng dụng cụ nấu, xử lý nấm đùi gà trước đến khi vừa chín.","Thêm cà rốt và đậu hũ trắng, đảo hoặc nướng ở nhiệt độ vừa để không bị khô.","Nêm bằng gia vị chay, kiểm tra độ chín và điều chỉnh vị theo khẩu phần.","Bày món ra đĩa, dùng khi còn ấm để giữ kết cấu — hoàn thiện phần chia sẻ cách làm trái cây hạt chia theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/4051765/pexels-photo-4051765.jpeg', NULL, N'published', 48, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(58, 10, N'BLOG', 32, N'Góc bếp: Quinoa rau củ nướng', N'noi-dung-thuan-chay-058', N'{"version":1,"story":"quinoa rau củ nướng làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":30,"servings":2,"nutrition":{"calories":346,"proteinG":19.6,"carbsG":41.8,"fatG":9.4,"fiberG":10.2,"sodiumMg":304},"ingredients":[{"name":"Quinoa","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái quinoa, nấm đùi gà thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cà rốt vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn quinoa rau củ nướng theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái quinoa, nấm đùi gà thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cà rốt vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn quinoa rau củ nướng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/18535641/pexels-photo-18535641.jpeg', NULL, N'published', 92, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(59, 11, N'BLOG', 39, N'Chia sẻ cách làm Đậu lăng hầm rau củ', N'noi-dung-thuan-chay-059', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như đậu lăng hầm rau củ. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":35,"servings":2,"nutrition":{"calories":363,"proteinG":21.3,"carbsG":43.9,"fatG":10.2,"fiberG":10.6,"sodiumMg":317},"ingredients":[{"name":"Đậu lăng đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế đậu lăng đỏ, nấm đùi gà; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm đậu lăng hầm rau củ theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế đậu lăng đỏ, nấm đùi gà; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm đậu lăng hầm rau củ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/17308057/pexels-photo-17308057.jpeg', NULL, N'published', 697, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(60, 12, N'BLOG', 46, N'Góc bếp: Bánh mì bơ đậu gà', N'noi-dung-thuan-chay-060', N'{"version":1,"story":"Mình tình cờ biết đến bánh mì bơ đậu gà trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":15,"servings":2,"nutrition":{"calories":380,"proteinG":23.0,"carbsG":46.0,"fatG":11.0,"fiberG":5.0,"sodiumMg":330},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Bánh mì nguyên cám","quantity":"100","unit":"g","isCustom":false},{"name":"Bơ","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị đậu gà và bánh mì nguyên cám, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp bơ với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần video hướng dẫn bánh mì bơ đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị đậu gà và bánh mì nguyên cám, cân đủ lượng cho khẩu phần.","Làm chín hoặc nghiền phần nhân chính đến độ mềm phù hợp.","Phối hợp bơ với nhân, nêm vừa miệng trước khi tạo hình hoặc phết lên bánh.","Nướng, áp chảo hoặc làm nóng tùy loại bánh cho đến khi bề mặt đạt độ vàng mong muốn.","Cắt và bày món, ăn ngay khi còn thơm — hoàn thiện phần video hướng dẫn bánh mì bơ đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/8253663/pexels-photo-8253663.jpeg', NULL, N'published', 17, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(61, 13, N'BLOG', 28, N'Chia sẻ cách làm Phở nấm thuần chay', N'noi-dung-thuan-chay-061', N'{"version":1,"story":"Điều mình thích ở phở nấm thuần chay là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":20,"servings":2,"nutrition":{"calories":297,"proteinG":12.7,"carbsG":34.1,"fatG":7.8,"fiberG":5.4,"sodiumMg":253},"ingredients":[{"name":"Nấm đùi gà","quantity":"150","unit":"g","isCustom":false},{"name":"Bún gạo","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm phở nấm thuần chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt nấm đùi gà, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm phở nấm thuần chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm phở nấm thuần chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt nấm đùi gà, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm phở nấm thuần chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/7166541/pexels-photo-7166541.jpeg', NULL, N'published', 36, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(62, 14, N'BLOG', 35, N'Góc bếp: Bún Huế chay', N'noi-dung-thuan-chay-062', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức bún Huế chay. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":25,"servings":2,"nutrition":{"calories":314,"proteinG":14.4,"carbsG":36.2,"fatG":8.6,"fiberG":5.8,"sodiumMg":266},"ingredients":[{"name":"Bún gạo","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của video hướng dẫn bún huế chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn bún huế chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của video hướng dẫn bún huế chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn bún huế chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/19106483/pexels-photo-19106483.jpeg', NULL, N'published', 113, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(63, 15, N'BLOG', 42, N'Chia sẻ cách làm Bún riêu đậu hũ chay', N'noi-dung-thuan-chay-063', N'{"version":1,"story":"bún riêu đậu hũ chay mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":30,"servings":2,"nutrition":{"calories":331,"proteinG":16.1,"carbsG":38.3,"fatG":9.4,"fiberG":6.2,"sodiumMg":279},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Bún gạo","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún riêu đậu hũ chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún riêu đậu hũ chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún riêu đậu hũ chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún riêu đậu hũ chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/19834448/pexels-photo-19834448.jpeg', NULL, N'published', 92, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(64, 16, N'BLOG', 49, N'Góc bếp: Hủ tiếu rau củ', N'noi-dung-thuan-chay-064', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu hủ tiếu rau củ. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":35,"servings":2,"nutrition":{"calories":348,"proteinG":17.8,"carbsG":40.4,"fatG":10.2,"fiberG":6.6,"sodiumMg":292},"ingredients":[{"name":"Bún gạo","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của video hướng dẫn hủ tiếu rau củ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn hủ tiếu rau củ theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của video hướng dẫn hủ tiếu rau củ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần video hướng dẫn hủ tiếu rau củ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/36934977/pexels-photo-36934977.jpeg', NULL, N'published', 229, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(65, 17, N'BLOG', 31, N'Chia sẻ cách làm Mì Quảng chay', N'noi-dung-thuan-chay-065', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là mì Quảng chay. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":15,"servings":2,"nutrition":{"calories":365,"proteinG":19.5,"carbsG":42.5,"fatG":11.0,"fiberG":7.0,"sodiumMg":305},"ingredients":[{"name":"Bún gạo","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm mì quảng chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm mì quảng chay theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm mì quảng chay theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt bún gạo, nấm hương thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho cà rốt và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm mì quảng chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/15662256/pexels-photo-15662256.jpeg', NULL, N'published', 467, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(66, 18, N'BLOG', 38, N'Góc bếp: Cơm gạo lứt đậu hũ sốt mè', N'noi-dung-thuan-chay-066', N'{"version":1,"story":"cơm gạo lứt đậu hũ sốt mè làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":20,"servings":2,"nutrition":{"calories":382,"proteinG":21.2,"carbsG":44.6,"fatG":11.8,"fiberG":7.4,"sodiumMg":318},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Gạo lứt","quantity":"100","unit":"g","isCustom":false},{"name":"Mè trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"15","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu hũ trắng, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho mè trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm gạo lứt đậu hũ sốt mè theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu hũ trắng, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho mè trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm gạo lứt đậu hũ sốt mè theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/25856552/pexels-photo-25856552.jpeg', NULL, N'under_review', 495, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(67, 19, N'BLOG', 45, N'Chia sẻ cách làm Cơm gạo lứt tempeh nướng', N'noi-dung-thuan-chay-067', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như cơm gạo lứt tempeh nướng. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":25,"servings":2,"nutrition":{"calories":399,"proteinG":22.9,"carbsG":46.7,"fatG":12.6,"fiberG":7.8,"sodiumMg":331},"ingredients":[{"name":"Tempeh","quantity":"150","unit":"g","isCustom":false},{"name":"Gạo lứt","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái tempeh, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm gạo lứt tempeh nướng theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái tempeh, gạo lứt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm gạo lứt tempeh nướng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/5056823/pexels-photo-5056823.jpeg', NULL, N'published', 54, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(68, 20, N'BLOG', 27, N'Góc bếp: Cơm chiên rau củ thuần chay', N'noi-dung-thuan-chay-068', N'{"version":1,"story":"Mình tình cờ biết đến cơm chiên rau củ thuần chay trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":30,"servings":2,"nutrition":{"calories":416,"proteinG":24.6,"carbsG":48.8,"fatG":13.4,"fiberG":8.2,"sodiumMg":344},"ingredients":[{"name":"Gạo trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"100","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái gạo trắng, cà rốt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cải thìa vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm chiên rau củ thuần chay theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái gạo trắng, cà rốt thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho cải thìa vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm chiên rau củ thuần chay theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/3297807/pexels-photo-3297807.jpeg', NULL, N'flagged', 97, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(69, 21, N'BLOG', 34, N'Chia sẻ cách làm Cơm bí đỏ đậu gà', N'noi-dung-thuan-chay-069', N'{"version":1,"story":"Điều mình thích ở cơm bí đỏ đậu gà là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":35,"servings":2,"nutrition":{"calories":433,"proteinG":11.3,"carbsG":50.9,"fatG":14.2,"fiberG":8.6,"sodiumMg":357},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Bí đỏ","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu gà, bí đỏ thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm bí đỏ đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái đậu gà, bí đỏ thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho gạo trắng vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần chia sẻ cách làm cơm bí đỏ đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/2679501/pexels-photo-2679501.jpeg', NULL, N'published', 75, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(70, 22, N'BLOG', 41, N'Góc bếp: Cơm nấm hương cải thìa', N'noi-dung-thuan-chay-070', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức cơm nấm hương cải thìa. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":15,"servings":2,"nutrition":{"calories":450,"proteinG":13.0,"carbsG":53.0,"fatG":15.0,"fiberG":9.0,"sodiumMg":370},"ingredients":[{"name":"Cải thìa","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Gạo trắng","quantity":"15","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái cải thìa, nấm hương thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho nấm đùi gà vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm nấm hương cải thìa theo khẩu vị trước khi phục vụ."],"steps":["Chuẩn bị phần cơm hoặc ngũ cốc đã nấu chín, để ráo và tơi hạt.","Rửa và thái cải thìa, nấm hương thành miếng nhỏ, tách riêng phần rau nhanh chín.","Làm nóng chảo, xào nguyên liệu cần lâu chín trước rồi cho nấm đùi gà vào.","Thêm cơm hoặc ngũ cốc, đảo trên lửa vừa đến khi gia vị bám đều.","Nếm lại, tắt bếp và trình bày với rau tươi hoặc mè nếu phù hợp — hoàn thiện phần video hướng dẫn cơm nấm hương cải thìa theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/142520/pexels-photo-142520.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 10, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(71, 23, N'BLOG', 48, N'Chia sẻ cách làm Cháo yến mạch nấm', N'noi-dung-thuan-chay-071', N'{"version":1,"story":"cháo yến mạch nấm mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":20,"servings":2,"nutrition":{"calories":467,"proteinG":14.7,"carbsG":55.1,"fatG":15.8,"fiberG":9.4,"sodiumMg":383},"ingredients":[{"name":"Yến mạch","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế yến mạch, nấm đùi gà; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm cháo yến mạch nấm theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế yến mạch, nấm đùi gà; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần chia sẻ cách làm cháo yến mạch nấm theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1753051/pexels-photo-1753051.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 907, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(72, 24, N'BLOG', 30, N'Góc bếp: Cháo đậu xanh bí đỏ', N'noi-dung-thuan-chay-072', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu cháo đậu xanh bí đỏ. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":25,"servings":2,"nutrition":{"calories":484,"proteinG":16.4,"carbsG":57.2,"fatG":16.6,"fiberG":9.8,"sodiumMg":396},"ingredients":[{"name":"Bí đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Yến mạch","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"100","unit":"g","isCustom":false},{"name":"Cải thìa","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"15","unit":"g","isCustom":false}],"instructions":["Rửa và sơ chế bí đỏ, yến mạch; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn cháo đậu xanh bí đỏ theo khẩu vị trước khi phục vụ."],"steps":["Rửa và sơ chế bí đỏ, yến mạch; cắt đều tay để nguyên liệu chín đồng đều.","Đun nước hoặc nước dùng rau củ đến sôi nhẹ, cho nguyên liệu lâu chín vào trước.","Thêm cà rốt, hạ lửa và nấu đến khi hỗn hợp đạt độ mềm mong muốn.","Khuấy nhẹ, nêm lại bằng gia vị chay và kiểm tra độ đặc của món.","Múc ra bát, dùng nóng cùng rau thơm hoặc tiêu tùy khẩu vị — hoàn thiện phần video hướng dẫn cháo đậu xanh bí đỏ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/56014/pizza-pizza-service-italian-eat-56014.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 34, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(73, 25, N'BLOG', 37, N'Chia sẻ cách làm Bún xào rau củ đậu hũ', N'noi-dung-thuan-chay-073', N'{"version":1,"story":"Một trong những món mình luôn muốn ăn lại là bún xào rau củ đậu hũ. Hương vị quen thuộc khiến bữa ăn giản dị cũng trở nên đáng nhớ.","prepMinutes":15,"cookMinutes":30,"servings":2,"nutrition":{"calories":501,"proteinG":18.1,"carbsG":59.3,"fatG":17.4,"fiberG":10.2,"sodiumMg":409},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Bún gạo","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"15","unit":"g","isCustom":false}],"instructions":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún xào rau củ đậu hũ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún xào rau củ đậu hũ theo khẩu vị trước khi phục vụ."],"steps":["Ngâm hoặc trụng phần sợi của chia sẻ cách làm bún xào rau củ đậu hũ theo hướng dẫn trên bao bì, để ráo.","Rửa và cắt đậu hũ trắng, bún gạo thành miếng vừa ăn; để riêng nguyên liệu cần nấu lâu.","Ninh rau củ và nấm với nước trên lửa vừa để lấy vị ngọt; vớt bọt nếu có.","Cho nấm hương và các nguyên liệu còn lại vào nồi, nêm vừa ăn bằng gia vị chay.","Xếp sợi vào tô, thêm phần nhân và chan nước dùng nóng; ăn ngay — hoàn thiện phần chia sẻ cách làm bún xào rau củ đậu hũ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1359326/pexels-photo-1359326.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 646, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(74, 26, N'BLOG', 44, N'Góc bếp: Mì soba sốt mè', N'noi-dung-thuan-chay-074', N'{"version":1,"story":"mì soba sốt mè làm mình nhớ những bữa cơm quây quần cùng gia đình. Mỗi lần thưởng thức đều có cảm giác gần gũi và ấm áp.","prepMinutes":20,"cookMinutes":35,"servings":2,"nutrition":{"calories":288,"proteinG":19.8,"carbsG":33.4,"fatG":7.2,"fiberG":10.6,"sodiumMg":422},"ingredients":[{"name":"Mè trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế mè trắng và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn mì soba sốt mè theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế mè trắng và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn mì soba sốt mè theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1640772/pexels-photo-1640772.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 371, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(75, 27, N'BLOG', 26, N'Chia sẻ cách làm Mì soba nấm cải bó xôi', N'noi-dung-thuan-chay-075', N'{"version":1,"story":"Có những ngày mình chỉ muốn một món nhẹ nhàng như mì soba nấm cải bó xôi. Không cầu kỳ, nhưng lại khiến tâm trạng dễ chịu hơn hẳn.","prepMinutes":25,"cookMinutes":15,"servings":2,"nutrition":{"calories":305,"proteinG":21.5,"carbsG":35.5,"fatG":8.0,"fiberG":5.0,"sodiumMg":435},"ingredients":[{"name":"Cải bó xôi","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế cải bó xôi và nấm đùi gà; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm mì soba nấm cải bó xôi theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế cải bó xôi và nấm đùi gà; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm mì soba nấm cải bó xôi theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1143754/pexels-photo-1143754.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 640, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(76, 28, N'BLOG', 33, N'Góc bếp: Pasta sốt cà chua đậu lăng', N'noi-dung-thuan-chay-076', N'{"version":1,"story":"Mình tình cờ biết đến pasta sốt cà chua đậu lăng trong một lần tìm món chay mới. Từ đó, đây trở thành lựa chọn thú vị mỗi khi muốn đổi vị.","prepMinutes":10,"cookMinutes":20,"servings":2,"nutrition":{"calories":322,"proteinG":23.2,"carbsG":37.6,"fatG":8.8,"fiberG":5.4,"sodiumMg":448},"ingredients":[{"name":"Đậu lăng đỏ","quantity":"150","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế đậu lăng đỏ và cà chua; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn pasta sốt cà chua đậu lăng theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế đậu lăng đỏ và cà chua; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho mì soba và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần video hướng dẫn pasta sốt cà chua đậu lăng theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/2284166/pexels-photo-2284166.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 343, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(77, 29, N'BLOG', 40, N'Chia sẻ cách làm Pasta sốt kem hạt điều', N'noi-dung-thuan-chay-077', N'{"version":1,"story":"Điều mình thích ở pasta sốt kem hạt điều là sự cân bằng giữa cảm giác thanh đạm và hương vị đặc trưng. Một lựa chọn dễ thương cho ngày bận rộn.","prepMinutes":15,"cookMinutes":25,"servings":2,"nutrition":{"calories":339,"proteinG":24.9,"carbsG":39.7,"fatG":9.6,"fiberG":5.8,"sodiumMg":461},"ingredients":[{"name":"Hạt điều","quantity":"150","unit":"g","isCustom":false},{"name":"Mì soba","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"100","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"15","unit":"g","isCustom":false},{"name":"Cải bó xôi","quantity":"15","unit":"g","isCustom":false}],"instructions":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế hạt điều và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm pasta sốt kem hạt điều theo khẩu vị trước khi phục vụ."],"steps":["Luộc mì đến độ chín vừa ăn, giữ lại ít nước luộc rồi để ráo.","Sơ chế hạt điều và mì soba; cắt miếng phù hợp để dễ quyện sốt.","Áp chảo phần nhân, cho cà chua và gia vị chay vào tạo thành sốt.","Cho mì vào chảo, đảo nhanh với sốt; thêm nước luộc nếu hỗn hợp quá khô.","Tắt bếp khi sợi mì đã thấm sốt, bày ra đĩa và dùng nóng — hoàn thiện phần chia sẻ cách làm pasta sốt kem hạt điều theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/1040685/pexels-photo-1040685.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'under_review', 120, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(78, 30, N'BLOG', 47, N'Góc bếp: Salad quinoa đậu gà', N'noi-dung-thuan-chay-078', N'{"version":1,"story":"Cuối tuần này mình dành thời gian thưởng thức salad quinoa đậu gà. Bữa ăn chậm rãi đôi khi là cách tốt nhất để tự chăm sóc bản thân.","prepMinutes":20,"cookMinutes":30,"servings":2,"nutrition":{"calories":356,"proteinG":11.6,"carbsG":41.8,"fatG":10.4,"fiberG":6.2,"sodiumMg":244},"ingredients":[{"name":"Đậu gà","quantity":"150","unit":"g","isCustom":false},{"name":"Quinoa","quantity":"100","unit":"g","isCustom":false},{"name":"Dưa leo","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false},{"name":"Bắp cải tím","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế đậu gà và quinoa, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu gà, quinoa và dưa leo với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn salad quinoa đậu gà theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế đậu gà và quinoa, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu gà, quinoa và dưa leo với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn salad quinoa đậu gà theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/2347311/pexels-photo-2347311.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 369, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(79, 31, N'BLOG', 29, N'Chia sẻ cách làm Salad kale bơ hạt', N'noi-dung-thuan-chay-079', N'{"version":1,"story":"salad kale bơ hạt mang đến một trải nghiệm rất riêng trong hành trình ăn chay của mình. Mình muốn chia sẻ cảm hứng đó với mọi người.","prepMinutes":25,"cookMinutes":35,"servings":2,"nutrition":{"calories":373,"proteinG":13.3,"carbsG":43.9,"fatG":11.2,"fiberG":6.6,"sodiumMg":257},"ingredients":[{"name":"Cải kale","quantity":"150","unit":"g","isCustom":false},{"name":"Dưa leo","quantity":"100","unit":"g","isCustom":false},{"name":"Bơ","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false},{"name":"Bắp cải tím","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu gà","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế cải kale và dưa leo, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều cải kale, dưa leo và bơ với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần chia sẻ cách làm salad kale bơ hạt theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế cải kale và dưa leo, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều cải kale, dưa leo và bơ với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần chia sẻ cách làm salad kale bơ hạt theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/979310/pexels-photo-979310.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 3446, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(80, 32, N'BLOG', 36, N'Góc bếp: Salad bắp cải tím đậu hũ', N'noi-dung-thuan-chay-080', N'{"version":1,"story":"Nếu đang tìm chút cảm hứng cho thực đơn hằng ngày, mình muốn giới thiệu salad bắp cải tím đậu hũ. Một món ăn khiến bàn ăn có thêm màu sắc.","prepMinutes":10,"cookMinutes":15,"servings":2,"nutrition":{"calories":390,"proteinG":15.0,"carbsG":46.0,"fatG":12.0,"fiberG":7.0,"sodiumMg":270},"ingredients":[{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Bắp cải tím","quantity":"100","unit":"g","isCustom":false},{"name":"Dưa leo","quantity":"100","unit":"g","isCustom":false},{"name":"Cà chua","quantity":"15","unit":"g","isCustom":false},{"name":"Đậu gà","quantity":"15","unit":"g","isCustom":false}],"instructions":["Sơ chế đậu hũ trắng và bắp cải tím, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu hũ trắng, bắp cải tím và dưa leo với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn salad bắp cải tím đậu hũ theo khẩu vị trước khi phục vụ."],"steps":["Sơ chế đậu hũ trắng và bắp cải tím, rửa kỹ rồi để thật ráo nước.","Luộc hoặc hấp riêng những nguyên liệu cần làm chín; để nguội trước khi trộn.","Pha nước trộn từ gia vị chay và chút vị chua, nếm cho cân bằng.","Trộn đều đậu hũ trắng, bắp cải tím và dưa leo với nước sốt ngay trước khi dùng.","Cho ra đĩa, thêm phần hạt hoặc rau thơm nếu có để giữ độ giòn — hoàn thiện phần video hướng dẫn salad bắp cải tím đậu hũ theo khẩu vị trước khi phục vụ."]}', NULL, N'https://images.pexels.com/photos/568370/pexels-photo-568370.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, N'published', 812, '2026-10-13T23:56:12.341', '2026-10-13T23:56:12.341'),
(81, 20, N'BLOG', 33, N'Chia sẻ cách làm Bánh xèo chay giòn rụm', N'noi-dung-thuan-chay-081', N'{"version":1,"story":"Cuối tuần này mình muốn thử một món có chút giòn rụm cho bữa tối. Bánh xèo chay giòn rụm là lựa chọn khiến cả nhà hào hứng ngay từ khi nghe mùi thơm trên chảo.","prepMinutes":20,"cookMinutes":15,"servings":3,"nutrition":{"calories":320,"proteinG":13.5,"carbsG":38.0,"fatG":12.4,"fiberG":5.2,"sodiumMg":410},"ingredients":[{"name":"Bột gạo","quantity":"200","unit":"g","isCustom":false},{"name":"Nước cốt dừa","quantity":"150","unit":"ml","isCustom":false},{"name":"Nấm đùi gà","quantity":"100","unit":"g","isCustom":false},{"name":"Giá đỗ","quantity":"80","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"50","unit":"g","isCustom":false}],"instructions":["Pha bột gạo với nước cốt dừa và chút muối, để nghỉ cho bột nở đều.","Rửa và cắt nấm đùi gà, giá đỗ, cà rốt thành miếng vừa ăn.","Làm nóng chảo, tráng một lớp bột mỏng rồi xếp nhân rau củ lên trên.","Đậy nắp cho bánh chín, mở nắp để bánh giòn rồi gấp đôi.","Bày bánh xèo chay giòn rụm ra đĩa và dùng ngay với rau sống."],"steps":["Pha bột gạo với nước cốt dừa và chút muối, để nghỉ cho bột nở đều.","Rửa và cắt nấm đùi gà, giá đỗ, cà rốt thành miếng vừa ăn.","Làm nóng chảo, tráng một lớp bột mỏng rồi xếp nhân rau củ lên trên.","Đậy nắp cho bánh chín, mở nắp để bánh giòn rồi gấp đôi.","Bày bánh xèo chay giòn rụm ra đĩa và dùng ngay với rau sống."],"tips":"Tráng bột mỏng để bánh giòn lâu."}', NULL, N'https://images.pexels.com/photos/3762089/pexels-photo-3762089.jpeg', NULL, N'published', 880, '2026-10-14T01:20:36.543', '2026-10-14T01:20:36.543'),
(82, 21, N'BLOG', 40, N'Chia sẻ cách làm Phở cuốn chay chấm tương', N'noi-dung-thuan-chay-082', N'{"version":1,"story":"Có những buổi chiều mình thích tự cuốn từng chiếc phở cuốn thật chậm. Phở cuốn chay chấm tương vừa nhẹ bụng vừa đủ đầy cho một bữa tối thanh đạm.","prepMinutes":25,"cookMinutes":10,"servings":2,"nutrition":{"calories":290,"proteinG":12.0,"carbsG":34.0,"fatG":9.5,"fiberG":4.8,"sodiumMg":380},"ingredients":[{"name":"Bánh phở cuốn","quantity":"200","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"150","unit":"g","isCustom":false},{"name":"Nấm hương","quantity":"80","unit":"g","isCustom":false},{"name":"Rau thơm","quantity":"50","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"50","unit":"g","isCustom":false}],"instructions":["Áp chảo đậu hũ trắng với chút gia vị chay cho vàng đều hai mặt.","Rửa sạch rau thơm, cà rốt và nấm hương; cắt sợi vừa cuốn.","Trải bánh phở cuốn, xếp đậu hũ và rau củ rồi cuốn chặt tay.","Pha nước chấm từ tương và chút vị chua ngọt cho cân bằng.","Xếp phở cuốn chay chấm tương ra đĩa và dùng kèm nước chấm."],"steps":["Áp chảo đậu hũ trắng với chút gia vị chay cho vàng đều hai mặt.","Rửa sạch rau thơm, cà rốt và nấm hương; cắt sợi vừa cuốn.","Trải bánh phở cuốn, xếp đậu hũ và rau củ rồi cuốn chặt tay.","Pha nước chấm từ tương và chút vị chua ngọt cho cân bằng.","Xếp phở cuốn chay chấm tương ra đĩa và dùng kèm nước chấm."],"tips":"Cuốn chặt tay để nhân không rơi."}', NULL, N'https://images.pexels.com/photos/1907244/pexels-photo-1907244.jpeg', NULL, N'published', 1020, '2026-10-14T01:20:36.543', '2026-10-14T01:20:36.543'),
(83, 22, N'BLOG', 36, N'Chia sẻ cách làm Cơm tấm chay sườn nấm', N'noi-dung-thuan-chay-083', N'{"version":1,"story":"Mình muốn làm mới bữa cơm quen thuộc bằng phiên bản chay. Cơm tấm chay sườn nấm vẫn giữ vị đậm đà nhưng nhẹ nhàng hơn cho bữa tối.","prepMinutes":20,"cookMinutes":25,"servings":2,"nutrition":{"calories":430,"proteinG":16.5,"carbsG":52.0,"fatG":14.0,"fiberG":6.0,"sodiumMg":460},"ingredients":[{"name":"Gạo tấm","quantity":"200","unit":"g","isCustom":false},{"name":"Nấm đùi gà","quantity":"150","unit":"g","isCustom":false},{"name":"Đậu hũ trắng","quantity":"100","unit":"g","isCustom":false},{"name":"Cà rốt","quantity":"50","unit":"g","isCustom":false},{"name":"Dưa leo","quantity":"50","unit":"g","isCustom":false}],"instructions":["Vo gạo tấm và nấu chín mềm, giữ hạt cơm tơi.","Ướp nấm đùi gà với nước tương và tiêu, áp chảo cho thơm.","Chiên đậu hũ trắng đến vàng đều rồi cắt miếng vừa ăn.","Pha nước chấm chay và chuẩn bị cà rốt, dưa leo cắt lát.","Xếp cơm tấm chay sườn nấm ra đĩa và dùng nóng."],"steps":["Vo gạo tấm và nấu chín mềm, giữ hạt cơm tơi.","Ướp nấm đùi gà với nước tương và tiêu, áp chảo cho thơm.","Chiên đậu hũ trắng đến vàng đều rồi cắt miếng vừa ăn.","Pha nước chấm chay và chuẩn bị cà rốt, dưa leo cắt lát.","Xếp cơm tấm chay sườn nấm ra đĩa và dùng nóng."],"tips":"Ướp nấm trước 10 phút để đậm vị."}', NULL, N'https://images.pexels.com/photos/723198/pexels-photo-723198.jpeg', NULL, N'published', 945, '2026-10-14T01:20:36.543', '2026-10-14T01:20:36.543');
